טו. כָּל דָּבָר שֶׁבָּעוֹלָם נִבְרָא עַל יְדֵי בְּחִינַת גִּימֶל סְפָרִים אֵלּוּ כַּמּוּבָא בְּסֵפֶר יְצִירָה הַנַּ"ל. כִּי כָּל דָּבָר שֶׁבָּעוֹלָם נִבְרָא רַק לְסַפֵּר וּלְהַגְדִּיל כְּבוֹדוֹ יִתְבָּרַךְ עַל יְדֵי זֶה, וְעַל כֵּן כָּל דָּבָר שֶׁבָּעוֹלָם כָּלוּל מִגִּימֶל בְּחִינוֹת אֵלּוּ הַסְּפָרִים הַנַּ"ל. כִּי בְּכָל דָּבָר שֶׁבָּעוֹלָם נִכְתַּב וְנֶחְקָק גְּדֻלָּתוֹ יִתְבָּרַךְ כְּמוֹ בְּהַסְּפָרִים מַמָּשׁ, רַק הַכֹּל עֲדַיִין בְּכֹחַ כְּמוֹ בִּבְחִינַת הַקְּלָף וְהַדְּיוֹ שֶׁהֵם בְּחִינַת סֵפֶר וְסוֹפֵר. וְעִקַּר הִתְגַּלּוּת כְּבוֹדוֹ יִתְבָּרַךְ עַל יְדֵי כָּל הַדְּבָרִים שֶׁבָּעוֹלָם הוּא רַק עַל יְדֵי הָאָדָם, שֶׁהוּא צָרִיךְ לַעֲסֹק בָּזֶה לְעַיֵּן וּלְהַבִּיט בָּזֶה הֵיטֵב וּלְסַפֵּר לַכֹּל כְּבוֹדוֹ וּגְדֻלָּתוֹ יִתְבָּרַךְ שֶׁמֵּבִין מִכָּל דָּבָר, וְהוּא כְּמוֹ בְּחִינַת הַכּוֹתֵב הַסְּפָרִים וּמְחַבֵּר הַדְּיוֹ עִם הַקְּלָף וּמְגַלֶּה וּמְצַיֵּר צוּרוֹת הָאוֹתִיּוֹת וְחוֹקְקָם עַל הַסֵּפֶר שֶׁזֶּה בְּחִינַת סִפּוּר. וַאֲפִלּוּ אַחַר כָּךְ כְּשֶׁכְּבָר נִכְתְּבוּ וְנֶחְקְקוּ הָאוֹתִיּוֹת עַל הַסֵּפֶר, עֲדַיִן אִם אֵין לוֹמְדִים בּוֹ אֵין בּוֹ תּוֹעֶלֶת וַהֲרֵי הוּא כְּגֹלֶם חַס וְשָׁלוֹם. וְעִקַּר שְׁלֵמוּת הַסְּפָרִים הוּא כְּשֶׁקּוֹרְאִין וְלוֹמְדִין בּוֹ וּמְלַמְּדִין גַּם לַאֲחֵרִים, כְּדֵי לְהוֹדִיעַ וּלְסַפֵּר לַכֹּל כְּבוֹדוֹ וּגְדֻלָּתוֹ יִתְבָּרַךְ שֶׁזֶּה עִקַּר כַּוָּנַת הַסֵּפֶר. וְכֵן הוּא עִקַּר כַּוָּנַת הַבְּרִיאָה שֶׁהוּא רַק בִּשְׁבִיל הִתְגַּלּוּת כְּבוֹדוֹ יִתְבָּרַךְ, עַל יְדֵי בְּחִינַת גִּימֶל סְפָרִים אֵלּוּ הַנַּ"ל (שם). 
טז. כְּפִי סֵדֶר הַבְּרִיאָה שֶׁכָּל קִיּוּמָהּ עַל יְדֵי הַתּוֹרָה שֶׁהַצַּדִּיקִים מַמְשִׁיכִין בְּכָל עֵת, עַל כֵּן הָיִינוּ צְרִיכִין שֶׁיַּמְשִׁיכוּ לָנוּ הִתְחַדְּשׁוּת הַתּוֹרָה בְּכָל יוֹם מֵחָדָשׁ כִּי בְּכָל יוֹם נִמְשָׁכִין מוֹחִין חֲדָשִׁים. וְעַל כֵּן הָיִינוּ צְרִיכִין בְּכָל יוֹם חִדּוּשֵׁי תּוֹרָה חֲדָשִׁים. אַךְ כָּל זֶה אִם הָיָה הַדּוֹר כְּתִקּוּנוֹ וּכְמוֹ שֶׁיִּהְיֶה בֶּאֱמֶת לֶעָתִיד, שֶׁאָז יִהְיוּ נִפְתָּחִין מַעֲיָנוֹת הַחָכְמָה וִיגַלּוּ לָנוּ הַצַּדִּיקִים חִדּוּשֵׁי תּוֹרָה נִפְלָאִים בְּכָל יוֹם. אֲבָל עַכְשָׁו בְּעֹמֶק גָּלוּתֵנוּ קָשֶׁה לְגַלּוֹת חִדּוּשֵׁי תּוֹרָה אֲמִתִּיִּים אֲפִלּוּ פַּעַם אַחַת בְּשָׁנָה. רַק הַשֵּׁם יִתְבָּרַךְ בְּרַחֲמָיו נָתַן כֹּחַ לְהַצַדִּיק הָאֱמֶת שֶׁיַּמְשִׁיךְ תּוֹרָה מִמָּקוֹם גָּבֹהַּ וְעֶלְיוֹן מְאֹד, מִבְּחִינַת אוֹרַיְיתָא דְּעַתִּיקָא, עַד שֶׁהַתּוֹרָה שֶׁלּוֹ מְאִירָה לָעוֹלָם וָעֶד כָּל יְמֵי עוֹלָם עַד לֶעָתִיד לָבֹא, שֶׁאָז יִתְגַּלֶּה אוֹרַיְיתָא דְּעַתִּיקָא בִּשְׁלֵמוּת. וְחִדּוּשֵׁי תּוֹרָתוֹ נִמְשָׁכִין בִּקְדֻשָּׁה נִפְלָאָה כָּזֹאת עַד שֶׁכָּל אֶחָד בְּבֵיתוֹ יָכוֹל לְהָאִיר עַל עַצְמוֹ אוֹר תּוֹרָתוֹ. עַד שֶׁאֲפִלּוּ אִם הוּא בַּדְּיוֹטָא הַתַּחְתּוֹנָה מְאֹד, אַף עַל פִּי כֵן תָּאִיר לוֹ אוֹר הַתּוֹרָה הַנַּ"ל, כְּמוֹ אוֹר וְנֵר לָצֵאת מֵחֶשְׁכַת אֲפֵלָתוֹ. כִּי כָּל אֶחָד אֵיךְ שֶׁהוּא יָכוֹל לִמְצֹא אֶת עַצְמוֹ בְּתוֹרָתוֹ, וְשֶׁתָּאִיר לוֹ לָנֶצַח לָצֵאת מֵאֲפֵלָה ל

